SELECT * FROM JSON_TABLE('[{"a":1,"b":[1,2]},{"a":"x"}]', '$[*]' COLUMNS (id FOR ORDINALITY, a int PATH '$.a', b jsonb PATH '$.b', e bool EXISTS PATH '$.b', NESTED PATH '$.b[*]' COLUMNS (bb int PATH '$')));
SELECT * FROM JSON_TABLE('[{"a":"x"}]', '$[*]' COLUMNS (a int PATH '$.a'));
SELECT * FROM JSON_TABLE('[{"a":"x"}]', '$[*]' COLUMNS (a int PATH '$.a') ERROR ON ERROR);
SELECT * FROM JSON_TABLE('[{"a":"x"}]', '$[*]' COLUMNS (a int PATH '$.a' ERROR ON ERROR));
SELECT * FROM JSON_TABLE('{"a":1}', 'strict $.b' COLUMNS (a int PATH '$.a'));
SELECT * FROM JSON_TABLE('{"a":1}', 'strict $.b' COLUMNS (a int PATH '$.a') ERROR ON ERROR);
SELECT * FROM JSON_TABLE('[1,2]', '$[*]' COLUMNS (a int PATH '$', n1 FOR ORDINALITY, NESTED '$' COLUMNS (x text PATH '$'), NESTED '$' COLUMNS (y text PATH '$')));
SELECT jt.* FROM (VALUES ('[1,2]'::jsonb)) v(j), JSON_TABLE(v.j, '$[*]' AS p COLUMNS (a int PATH '$', b text)) jt;
SELECT * FROM JSON_TABLE('{"a": {"b": 1}}', '$' COLUMNS (a jsonb PATH '$.a', a2 text FORMAT JSON PATH '$.a', c int PATH '$.c' DEFAULT 5 ON EMPTY, q text PATH '$.a' WITH WRAPPER));
SELECT * FROM JSON_TABLE('[{"k": "a", "v": 1}, {"k": "b", "v": 2}]', '$[*] ? (@.v > $min)' PASSING 1 AS min COLUMNS (k text, v int));
SELECT * FROM JSON_TABLE('[1]', '$[*]' COLUMNS (a int PATH '$', a text PATH '$'));
SELECT * FROM JSON_TABLE('[1]', '$[*]' COLUMNS (a int PATH '$')) AS t(x);
SELECT t.* FROM JSON_TABLE(NULL::jsonb, '$[*]' COLUMNS (a int PATH '$')) t;
SELECT * FROM JSON_TABLE('{"a": [{"b": [1, 2]}, {"b": [3]}]}', '$.a[*]' COLUMNS (o FOR ORDINALITY, NESTED PATH '$.b[*]' COLUMNS (o2 FOR ORDINALITY, b int PATH '$')));
CREATE TABLE jtt (id int, doc jsonb);
INSERT INTO jtt VALUES (1, '{"items": [{"n": "x", "q": 2}, {"n": "y", "q": 3}]}'), (2, '{"items": []}'), (3, NULL);
SELECT id, t.* FROM jtt, JSON_TABLE(doc, '$.items[*]' COLUMNS (n text PATH '$.n', q int PATH '$.q')) t ORDER BY id, n;
SELECT id, t.* FROM jtt LEFT JOIN LATERAL JSON_TABLE(doc, '$.items[*]' COLUMNS (n text PATH '$.n')) t ON true ORDER BY id, n;
SELECT sum(q) FROM jtt, JSON_TABLE(doc, '$.items[*]' COLUMNS (q int PATH '$.q'));
DROP TABLE jtt;
SELECT * FROM JSON_TABLE('[1]', 1 COLUMNS (a int PATH '$'));
SELECT * FROM JSON_TABLE('[1]', '$[' COLUMNS (a int PATH '$'));
SELECT * FROM JSON_TABLE('{"a":"2024-01-02"}', '$' COLUMNS (d date PATH '$.a', t text PATH '$.a', n numeric PATH '$.z' DEFAULT 1.5 ON EMPTY, ex int EXISTS PATH '$.a'));
EXPLAIN (COSTS OFF) SELECT * FROM JSON_TABLE('[1]', '$[*]' COLUMNS (a int PATH '$')) t;
EXPLAIN (COSTS OFF, VERBOSE) SELECT * FROM JSON_TABLE('[1]', '$[*]' COLUMNS (a int PATH '$')) t;
EXPLAIN (COSTS OFF, VERBOSE) SELECT * FROM JSON_TABLE('[1]'::jsonb, '$[*]' AS p PASSING 1 AS x, 'a' AS y COLUMNS (a int PATH '$', o FOR ORDINALITY, j jsonb PATH '$', t text FORMAT JSON PATH '$', e int EXISTS PATH '$' TRUE ON ERROR, d int PATH '$.d' DEFAULT 3 ON EMPTY ERROR ON ERROR, NESTED PATH '$' COLUMNS (b text PATH '$.b'), NESTED PATH '$' AS n2 COLUMNS (c text PATH '$.c', NESTED PATH '$' COLUMNS (cc int PATH '$.cc'))) ERROR ON ERROR);
EXPLAIN (COSTS OFF, VERBOSE) SELECT * FROM JSON_TABLE('{}', '$' COLUMNS (q text PATH '$' WITH CONDITIONAL WRAPPER OMIT QUOTES EMPTY ARRAY ON EMPTY));
CREATE VIEW jtv AS SELECT * FROM JSON_TABLE('[1]', '$[*]' COLUMNS (a int PATH '$', o FOR ORDINALITY, NESTED PATH '$' COLUMNS (b text PATH '$.b'))) t;
SELECT pg_get_viewdef('jtv'::regclass, true);
SELECT pg_get_viewdef('jtv'::regclass);
SELECT * FROM jtv;
DROP VIEW jtv;
CREATE TABLE jtt2 (doc jsonb);
CREATE VIEW jtv2 AS SELECT t.* FROM jtt2, JSON_TABLE(doc, '$.items[*]' AS items PASSING 2 AS lim COLUMNS (n text PATH '$.n' DEFAULT 'none' ON EMPTY, q int PATH '$.q ? (@ > $lim)' NULL ON ERROR, w jsonb PATH '$' WITH WRAPPER, ex bool EXISTS PATH '$.q' ERROR ON ERROR) ERROR ON ERROR) t;
SELECT pg_get_viewdef('jtv2'::regclass, true);
DROP VIEW jtv2;
DROP TABLE jtt2;
